properties.query:
[concat('let stallHours = ', string(parameters('ingestionStallHours')), ';
let baseline =
    MicrosoftPurviewInformationProtection
    | where TimeGenerated between (ago(7d) .. ago(1d))
    | summarize HourlyAvg = count() / 144.0;
let recent =
    MicrosoftPurviewInformationProtection
    | where TimeGenerated > ago(stallHours * 1h)
    | summarize Recent = count();
baseline
| extend dummy = 1
| join kind=inner (recent | extend dummy = 1) on dummy
| where HourlyAvg >= 1.0 and Recent == 0
| extend AlertReason = strcat("No rows in MicrosoftPurviewInformationProtection for last ", stallHours, "h. 7d hourly baseline: ", round(HourlyAvg,2))
| project AlertReason, HourlyAvg, Recent')]

let baseline = MicrosoftPurviewInformationProtection | where TimeGenerated between (ago(7d) .. ago(24h)) | summarize BaselineRows = count();
let recent = MicrosoftPurviewInformationProtection | where TimeGenerated > ago(24h) | summarize RecentRows = count(), LastSeen = max(TimeGenerated);
baseline | extend dummy = 1 | join kind=inner (recent | extend dummy = 1) on dummy
| project BaselineRows, RecentRows, LastSeen, HoursSinceLastEvent = datetime_diff('hour', now(), LastSeen)
